<script setup>
import { ref, onMounted } from 'vue';
import { api, send, isAdmin } from './api';
const members=ref([]),q=ref(''),offset=ref(0),error=ref(''),busy=ref(false);
async function search(next=false){if(!next)offset.value=0;busy.value=true;error.value='';try{const batch=await api('/admin/members?q='+encodeURIComponent(q.value)+'&after='+offset.value);members.value=next?[...members.value,...batch]:batch;offset.value+=batch.length;}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function change(m){busy.value=true;try{await send('/admin/members/'+encodeURIComponent(m.id)+'/coach',{enabled:!m.roles.includes('Coach')},'PUT');await search();}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(()=>{if(isAdmin())search();});
</script>
<template><div v-if="!isAdmin()" class="card"><h1>Administrator access required.</h1></div><template v-else><div class="page-heading"><div><p class="eyebrow">CONTROLLED ACCESS</p><h1>The right people<span class="lime-dot">.</span></h1><p>Approve coach access only after checking their identity and suitability.</p></div></div><section class="card"><form class="search-row" @submit.prevent="search()"><label>Find a member by email<input v-model="q" type="search" maxlength="100"></label><button :disabled="busy">Search</button></form><p v-if="error" class="error" role="alert">{{error}}</p><div class="table-scroll"><table><thead><tr><th>Member</th><th>Email</th><th>Access</th><th>Action</th></tr></thead><tbody><tr v-for="m in members" :key="m.id"><td>{{m.displayName||'Member'}}</td><td>{{m.email}}</td><td>{{m.roles.join(', ')||'Student'}}</td><td><button class="secondary" :disabled="busy" @click="change(m)">{{m.roles.includes('Coach')?'Remove coach access':'Approve coach access'}}</button></td></tr></tbody></table></div><button v-if="members.length&&members.length%30===0" class="text-button" :disabled="busy" @click="search(true)">Load more members</button><p class="hint">This screen cannot grant administrator access. Bootstrap the initial administrator through the server console.</p></section></template></template>
